create table public.customer_refunds (id uuid, business_id uuid, customer_id uuid, refund_number text, refund_date date, amount numeric, currency text, method text, reference text, notes text, lifecycle_state text, idempotency_key uuid, created_at timestamp with time zone, created_by uuid, updated_at timestamp with time zone, updated_by uuid, recorded_at timestamp with time zone, recorded_by uuid, financial_locked_at timestamp with time zone, voided_at timestamp with time zone, voided_by uuid, void_reason text);
